/** Contribution branch names are generated by the server only — never from request data (issue #11). */
export function newContributionId(now = Date.now()): string {
  const random = [...crypto.getRandomValues(new Uint8Array(5))].map((byte) => byte.toString(16).padStart(2, '0')).join('');
  return `${now.toString(36)}-${random}`;
}

export const contributionBranch = (id: string) => `contribute/${id}`;
